const motor={c:null,master:null,osc:[],noise:null,filter:null,whine:null,profile:null,active:false,start(){if(this.active)return;const C=window.AudioContext||window.webkitAudioContext;if(!C)return;this.c??=new C;this.c.resume();this.profile=engineProfiles[drivers[selected].sound]||engineProfiles.i4;const c=this.c,t=c.currentTime,master=c.createGain(),comp=c.createDynamicsCompressor(),filter=c.createBiquadFilter();master.gain.setValueAtTime(.0001,t);master.gain.exponentialRampToValueAtTime(.145,t+.18);filter.type='lowpass';filter.frequency.value=this.profile.filter;master.connect(filter).connect(comp).connect(c.destination);this.master=master;this.filter=filter;this.osc=this.profile.waves.map(([type,mul,gain])=>{const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=42*mul;g.gain.value=gain;o.connect(g).connect(master);o.start();return{o,g,mul}});const b=c.createBuffer(1,c.sampleRate*2,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(.35+Math.sin(i*.023)*.15);const n=c.createBufferSource(),nf=c.createBiquadFilter(),ng=c.createGain();n.buffer=b;n.loop=true;nf.type='bandpass';nf.frequency.value=360;nf.Q.value=.7;ng.gain.value=this.profile.noise;n.connect(nf).connect(ng).connect(master);n.start();this.noise={n,nf,ng};const wo=c.createOscillator(),wg=c.createGain();wo.type='sine';wo.frequency.value=900;wg.gain.value=.0001;wo.connect(wg).connect(master);wo.start();this.whine={o:wo,g:wg};this.active=true},set(rpm,load=.7){if(!this.active)return;const t=this.c.currentTime,base=Math.max(30,rpm/this.profile.div);this.osc.forEach(x=>x.o.frequency.setTargetAtTime(base*x.mul,t,.045));this.filter.frequency.setTargetAtTime(this.profile.filter+rpm*.12,t,.07);this.noise.nf.frequency.setTargetAtTime(210+rpm*.065,t,.06);this.noise.ng.gain.setTargetAtTime(this.profile.noise*(.5+load),t,.06);this.whine.o.frequency.setTargetAtTime(650+rpm*.23,t,.08);this.whine.g.gain.setTargetAtTime((this.profile.whine||0)*Math.max(0,(rpm-3000)/5000),t,.08)},shift(){if(!this.active)return;const t=this.c.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.setValueAtTime(.145,t);this.master.gain.exponentialRampToValueAtTime(.03,t+.06);this.master.gain.exponentialRampToValueAtTime(.145,t+.17);const o=this.c.createOscillator(),g=this.c.createGain();o.type='square';o.frequency.setValueAtTime(72,t);o.frequency.exponentialRampToValueAtTime(38,t+.1);g.gain.setValueAtTime(.08,t);g.gain.exponentialRampToValueAtTime(.0001,t+.12);o.connect(g).connect(this.c.destination);o.start();o.stop(t+.13)},stop(){if(!this.active)return;const t=this.c.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.setTargetAtTime(.0001,t,.08);const old=[...this.osc],noise=this.noise,whine=this.whine;setTimeout(()=>{old.forEach(x=>{try{x.o.stop()}catch{}});try{noise.n.stop()}catch{}try{whine.o.stop()}catch{}},500);this.active=false}};
function draw(t){const w=innerWidth,h=innerHeight,d=drivers[selected],age=(t-start)/1000,launch=Math.max(0,age-1),speed=Math.min(d.topSpeed,38+launch*(d.topSpeed/5.4)),curve=Math.sin(age*.52)*.17+pointer*.22;ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#030306');sky.addColorStop(.48,'#101117');sky.addColorStop(1,'#020203');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle='#07080a';ctx.beginPath();ctx.moveTo(0,h*.34);for(let x=0;x<=w;x+=35)ctx.lineTo(x,h*(.31+Math.sin(x*.009+age*.15)*.065));ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();const cx=w*(.5+curve);ctx.fillStyle='#17191d';ctx.beginPath();ctx.moveTo(cx-w*.055,h*.38);ctx.lineTo(cx+w*.055,h*.38);ctx.lineTo(w*1.2,h);ctx.lineTo(-w*.2,h);ctx.fill();for(let i=0;i<25;i++){const z=(i/25+launch*.018)%1,y=h*.39+z*z*h*.68,half=w*(.035+z*z*.53);ctx.strokeStyle=`rgba(245,245,240,${z*.72})`;ctx.lineWidth=1+z*3;ctx.beginPath();ctx.moveTo(cx-half,y);ctx.lineTo(cx-half-w*.025*z,y+10+z*44);ctx.stroke();ctx.beginPath();ctx.moveTo(cx+half,y);ctx.lineTo(cx+half+w*.025*z,y+10+z*44);ctx.stroke()}for(let i=0;i<34;i++){const z=(i/34+launch*.025)%1,y=h*.42+z*z*h*.58;ctx.strokeStyle=`rgba(255,255,255,${z*.18})`;ctx.beginPath();ctx.moveTo(w*.5+(i%2?1:-1)*w*.04,y);ctx.lineTo(w*.5+(i%2?1:-1)*w*.45,y+z*45);ctx.stroke()}const s=Math.round(speed),rpm=Math.round(1100+Math.min(d.redline-1100,launch*1550)),gear=Math.min(5,1+Math.floor(launch/1.15));if(gear!==lastGear){motor.shift();lastGear=gear}motor.set(rpm,.55+Math.abs(curve));$('[data-run-speed]',theatre).textContent=String(s).padStart(3,'0');$('[data-run-rpm]',theatre).textContent=rpm.toLocaleString();$('[data-run-gear]',theatre).textContent=String(gear);$('.run-status',theatre).textContent=age<1?'HOLD':age<2.1?'LAUNCH':age<4.6?'ATTACK THE APEX':age<7?'FULL THROTTLE':'LIMIT / '+d.tag;theatre.style.setProperty('--run',String(Math.min(1,launch/5)));theatre.style.setProperty('--curve',String(curve));raf=requestAnimationFrame(draw)}
function launch(i=selected){choose(i);const d=drivers[i];runArt.src=d.art;runArt.alt=`${d.name} night run`;$('.run-title',theatre).textContent=d.name;$('[data-run-car]',theatre).textContent=d.car;$('[data-run-engine]',theatre).textContent=d.engine;$('[data-run-limit]',theatre).textContent=`TOP SPEED / ${d.topSpeed} KM/H · TRACTION / LIVE`;theatre.dataset.engine=d.sound;theatre.style.setProperty('--accent',d.accent);if(!theatre.open)theatre.showModal();document.body.style.overflow='hidden';cancelAnimationFrame(raf);motor.stop();stopRealEngine();lastGear=1;start=performance.now();size();motor.start();startRealEngine(i);raf=requestAnimationFrame(draw)}
$('.garage-run',garage).onclick=()=>launch();$('.run-replay',theatre).onclick=()=>launch();$('.run-close',theatre).onclick=()=>{cancelAnimationFrame(raf);motor.stop();stopRealEngine();theatre.close();document.body.style.overflow=''};theatre.addEventListener('close',()=>{cancelAnimationFrame(raf);motor.stop();stopRealEngine();document.body.style.overflow=''});theatre.onpointermove=e=>{pointer=e.clientX/innerWidth-.5;theatre.style.setProperty('--tx',String(pointer))};addEventListener('resize',size);size();
