const touge=$('.touge');touge.insertAdjacentHTML('afterbegin','<img class="descent-art" src="/hero-touge.png" alt="AE86 carving through a wet mountain pass"><div class="descent-grade"></div><div class="descent-gates" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="descent-clock"><small>AKINA / SECTOR 03</small><b>03:17.42</b><span>WET ASPHALT · 184 KM/H</span></div>');touge.insertAdjacentHTML('beforeend','<div class="descent-hud"><span>APEX / 07</span><b>4</b><i>HEEL + TOE</i><button data-cursor="ENTER">CHASE CAMERA</button></div>');$('.descent-hud button',touge).onclick=()=>launch(0);
