const speedSection=$('.speed');speedSection.id='speed';speedSection.insertAdjacentHTML('beforeend','<div class="speed-live"><small>08 / DRIVER INPUT</small><b data-live-speed>180</b><span>KM/H</span><button data-throttle>HOLD THROTTLE</button><button data-shift>SHIFT UP</button></div>');let throttleTimer=0,liveSpeed=180,liveRpm=4200,liveGear=3;const live=()=>{$('[data-live-speed]').textContent=Math.round(liveSpeed);speedSection.style.setProperty('--live',String((liveSpeed-160)/70));motor.set(liveRpm,1)};const throttleOn=()=>{motor.start();clearInterval(throttleTimer);throttleTimer=setInterval(()=>{liveSpeed=Math.min(229,liveSpeed+.9);liveRpm=Math.min(8900,liveRpm+115);live()},32)};const throttleOff=()=>{clearInterval(throttleTimer);throttleTimer=setInterval(()=>{liveSpeed=Math.max(174,liveSpeed-.45);liveRpm=Math.max(2900,liveRpm-90);live();if(liveSpeed<=174){clearInterval(throttleTimer);motor.stop()}},36)};$('[data-throttle]').onpointerdown=throttleOn;$('[data-throttle]').onpointerup=throttleOff;$('[data-throttle]').onpointerleave=throttleOff;$('[data-shift]').onclick=()=>{motor.start();motor.shift();liveGear=Math.min(5,liveGear+1);liveRpm=Math.max(3800,liveRpm-2100);live()};
const night=$('.night');night.insertAdjacentHTML('afterbegin','<img class="night-art" src="/ryosuke-fc.png" alt="White FC emerging through rain on a mountain road"><div class="night-fog" aria-hidden="true"></div><div class="night-road" aria-hidden="true"><i></i><i></i></div>');night.insertAdjacentHTML('beforeend','<div class="night-rain" aria-hidden="true"></div><div class="night-meta"><small>09 / MIDNIGHT ATTACK</small><b>LIGHTS OFF.<br>INSTINCT ON.</b><span>AKAGI · 03:17 · HEAVY FOG</span></div><button class="night-launch" data-cursor="ENTER">BEGIN ZERO-VISIBILITY RUN</button>');$('.night-launch',night).onclick=()=>launch(2);night.onclick=e=>{if(e.target===night)launch(2)};
